"""Render only measured replay outcomes and exact independent review scope."""
from dental_release.paths import expand as _release_expand
import json
from pathlib import Path
from prepare_replay import HERE, sha, write

def read(p):
    return json.loads(Path(p).read_text())

def time_text(value):
    return f'{value:.3f} s'

def main():
    contract = read(HERE / 'FROZEN_FRONT_X86B.json')
    ledger = read(HERE / 'raw/x86b/FRONT_REPLAY.json')
    runs = {r['demo_id']: r for r in ledger['records']}
    hashes = {r['demo_id']: r for r in ledger['hashes_after']['records']}
    assert set(runs) == set(contract['front_ids']) and len(runs) == 12
    seconds = ledger.get('wall_seconds', ledger['wall_seconds_before_report'])
    original = (HERE / 'raw/x86b/history/FRONT.md').read_text()
    prefix = original.split('## Run 96 demon')[0]
    paragraph = _release_expand(f"""## Run de 12 front demon with a command\n\n```bash\ncd @DENTAL_IMPLEMENTATIONS@/X86_FRONT12\n./run_demos.sh\n```\n\n**{ledger['pass_count']}/12 PASS · {ledger['failure_count']} execution/gate error · {time_text(seconds)} total command time.**Timeout** 3 600 s **; maximum four numeric threads. PASS means that the specified run profile's original bounds holds . Physical FAIL and UNKNOWN in the table remain. R3 , GENCAD V6 and milling access uses short controls and frozen data; other runs use their existing packaged profiles. R3 : s 72 result is not recalculated. [Exact profiles and times](ALL_DEMOS.md) · [fresh receipts](raw/x86b/FRONT_REPLAY.json).\n\nThe selection is exactly the twelve below operations. Network's older R3 belongs to the history and hash-checked; its R4 is running. The interrupted 97 round is preserved as history. **{ledger['hashes_after']['pass_count']}/{ledger['hashes_after']['checked']} frozen resultshashar tally**, including three new reviewed versions and hunting 3 : s rejected version. Other **88** demo/status versions have **only hash control in this round**, no numerical rerun . A hash-PASS applies to retained prey. [Hashkvitton](raw/x86b/RESULT_HASHES.json).\n\nEach execution receives a new writable package instance and shared write protected local inputs. Linux, bubblewrap and existing Python environments are required; installation on empty workstation is untested. Four operating R7 bindings are used in the copy; the original numerical requirements are retained. This X86b delivery is waiting for independent review. Review 26 – 27 : s NOT_READY previously referred to unfinished snapshots and does not change here.\n\n## Try the sub-surgical surgery that the lab can use\n\n| Run operation | Limited result | Proven / calibrated / modeled / unknown | Rerun X86b/profile | Tid |\n|---|---|---|---|---|\n""")
    old_table = original.split('## Try the sub-surgical surgery that the lab can use')[1].split('Power issues retain')[0]
    row_text = {}
    for line in old_table.splitlines():
        if line.startswith('| `./run_demos.sh '):
            ident = line.split('`./run_demos.sh ', 1)[1].split('`', 1)[0]
            if ident in runs:
                row_text[ident] = line.rstrip().rstrip('|').rstrip()
    assert set(row_text) == set(runs)
    row_text['GENCAD_V6'] = row_text['GENCAD_V6'].replace('Separate **247 / 1 728** roof questions and **2 / 18** full crown slots with spatial contact.', 'If you have a fixed pose, **247 / 1 728** roof questions and **2 / 18** full crown seats. The separate R5 sample over all displacements provides **0/1 728** and **0/18** distinguishing queries and no passed suggestions.')
    for ident in contract['front_ids']:
        r = runs[ident]
        profile = 'fast control + hash' if ident in ['PROOF_LANE_FULL_CROWN_R3', 'GENCAD_V6', 'X53'] else 'befintlig paketprofil'
        mismatch = '0 mismatch' if r['mismatch_count'] == 0 else 'mismatch UNKNOWN' if r['mismatch_count'] is None else str(r['mismatch_count']) + ' mismatch'
        paragraph += f"{row_text[ident]} | **{r['status']}**, {mismatch}; {profile} | {time_text(r['wall_seconds'])} |\n"
    latest = '\n## Latest reviewed versions — hash checks in this round\n\n| Version | What the Review Decides | X86b / knowledge limit |\n|---|---|---|\n'
    new_rows = {r['demo_id']: r for r in contract['rows'][-3:] + contract['rejections']}
    descriptions = {'PROOF_LANE_FULL_CROWN_DIAG': ('ACCEPTED_WITH_CORRECTION: **0/72** form+funktion; **10/72** konstruktionsattrition. Natural bilateral pairs are a digital reference.', 'Review 26 recalculated existing measurements at **694,530 s**, max deviation **0 mm**. Five weak controls was corrected. Clinically accepted pair and physical contact **UNKNOWN**.'), 'PROOF_LANE_FULL_CROWN_R4': ('ACCEPTED_WITH_CORRECTION: **0/108** tekniska konjunktioner. Form pass **5 / 6 molar, 6 / 6 premolar, 1 / 6 anterior**; wall **0 / 6** per type.', 'Original exteriors miss virtual wall requirements **18 / 18**. Review 27 ran three fresh exports; copy codehash was corrected. **No parade improvement against R1 – R3** is shown; C/D is adaptive on the same test set.'), 'LANE_XBREAK_HUNT_3': ('**REJECT/NOT_READY** in review 25, latest existing decisions for hunting 3; no replacement review in batch 26 – 27.', '**1,019891 N** reproduceras i balkscenario. Exact summary test, independent assembly measurement and agreed demo format are missing. The rejection remains.'), 'LANE_XBREAK_HUNT_4': ('ACCEPTED_WITH_CORRECTION in review 27 : source rituals in **7 rounds** holds ; robust **5 %** forecast requirements fails .', '**R7 exact summary FAIL**: max identity error **2,842170943040401 e − 14 min**. Category breakdown first time moments are minimum extensions for the medieval question. **target_id =null**, graph registration blocked; no clinical recommendation.')}
    for ident in ['PROOF_LANE_FULL_CROWN_DIAG', 'PROOF_LANE_FULL_CROWN_R4', 'LANE_XBREAK_HUNT_3', 'LANE_XBREAK_HUNT_4']:
        r = new_rows[ident]
        h = hashes[ident]
        (desc, limit) = descriptions[ident]
        review = Path(r['independent_review_binding']['review_locator']).relative_to(HERE.parent)
        latest += f"| [{ident}](../{review}) | {desc} | **{h['status']}**, {time_text(h['wall_seconds'])}; **no new rerun**. {limit} |\n"
    suffix = 'Power issues retain' + original.split('Power issues retain', 1)[1]
    start = 'The strong controls reproduce'
    if start in suffix:
        (before, tail) = suffix.split(start, 1)
        rest = tail.split('## Maintain the divestiture and knowledge boundaries', 1)[1]
        suffix = before + 'The strong controls reproduce the height/power responses within the frozen tolerances. No algorithm advantage is claimed. Two administrative state has exactly the same **12 identities, profiles and frozen result expectations**: the summary byte and floating point identity errors are **0**. An injected error receipt changes the original approval with **1**. For this particular couple, the smallest extension is a piece of approval. Identity and hash expectations are therefore not enough without actual validation. It is an administrative witness, no physical conclusion. [Satisfactory tests and misinjections executed](raw/x86b/FRONT_REPLAY.json).\n\n## Maintain the divestiture and knowledge boundaries\n' + rest
    suffix = suffix.replace('Of **8** new version reviews', 'In the earlier batch 23-25 expansion: of **8** version reviews')
    suffix = suffix.replace('![Execution scope, runtime and laboratory queries](PACKAGE_AND_LAB.png)', '![The twelve run profiles and their actual times](PACKAGE_AND_LAB_X86B.png)')
    (HERE / 'FRONT.md').write_text(prefix + paragraph + latest + '\n' + suffix)
    lines = ['# All demos: actual rerun and frozen result', '', f"X86b ran **{ledger['pass_count']}/12 PASS**, {ledger['failure_count']} error in **{time_text(seconds)}** with 60-minute limit. All times are observed PHENOMENOLOGICAL running costs. Three new reviewed versions are included in the hash-bound overview; hunting 3 is reported separately as rejected.", '', "PASS applies to the current running profile's program gate. HASH_PASS means byte identity without numerical rerun . No physical knowledge status is changed by these labels. Historical trials are found in raw/prior_runs and raw/x86b/history; their times and outcomes are not used as fresh PASS.", '', '| ID | Query / result | Knowledge level and resolution | Review | X86b actual outcome | Profil / tid |', '|---|---|---|---|---|---|']
    for row in contract['rows'] + contract['rejections']:
        ident = row['demo_id']
        h = hashes[ident]
        r = runs.get(ident)
        if r:
            count = 'UNKNOWN' if r['mismatch_count'] is None else str(r['mismatch_count'])
            status = f"**{r['status']}**; mismatch {count}; {h['status']}"
            profile = 'fast control + frozen data' if ident in ['PROOF_LANE_FULL_CROWN_R3', 'GENCAD_V6', 'X53'] else 'befintlig paketerad profil'
            timing = f"{profile}; {time_text(r['wall_seconds'])}; [fresh receipt](raw/x86b/FRONT_REPLAY.json)"
        else:
            status = f"**{h['status']}**; {h['mismatch_count']} hashmis match; not overtaken"
            timing = f"only resulthash; {time_text(h['wall_seconds'])}; [hashkvitto](raw/x86b/RESULT_HASHES.json)"
        review = row['delivery_review_status']
        if row.get('independent_review_binding'):
            rp = Path(row['independent_review_binding']['review_locator']).relative_to(HERE.parent)
            review = f'[{review}](../{rp})'
        lines.append(f"| `{ident}` | {row['label']}; {row['reader_result']} | {row['knowledge_status']}; {row['resolution']} | {review} | {status} | {timing} |")
    lines += ['', "Network's R3 is hashically controlled and maintains its negative completeness gate. NET_R4 is the executed successor. Jakt3 is still rejected. Jakt4 : s exact numerical adequacy requirements fails and graph targets are missing. X86b : s own independent review is PENDING ."]
    (HERE / 'ALL_DEMOS.md').write_text('\n'.join(lines) + '\n')
    result = {'schema': 'dental-sunday-refresh/v2', 'round_tag': 'X86b-sunday-refresh', 'claim_type': 'capability', 'review_state': 'PENDING_INDEPENDENT_REVIEW', 'outcome': ledger['status'], 'capability': 'One command runs exactly12 bounded front profiles in clean writable copies; other frozen results are hash-verified and latest review scopes are bound', 'front_pass_count': ledger['pass_count'], 'front_requested': contract['front_ids'], 'front_failure_count': ledger['failure_count'], 'command_wall_seconds': seconds, 'wall_budget_seconds': 3600, 'hashes_checked': ledger['hashes_after']['checked'], 'hash_pass_count': ledger['hashes_after']['pass_count'], 'hash_mismatch_count': ledger['hashes_after']['mismatch_count'], 'eligible_registry_count': len(contract['rows']), 'eligible_hash_only_count': len(contract['rows']) - 12, 'rejected_version_count': 1, 'physical_measurements': 0, 'scientific_status_promotions': 0, 'status_counts': {'PRESENT': 7, 'PARTIAL': 39, 'REFUTED': 2, 'RESEARCH': 3, 'MISSING': 1}, 'external_referent': {'kind': 'external_review', 'locator': [str(HERE.parent / f'LANE_XREVIEW_BATCH{b}/RESULTS.md') for b in [25, 26, 27]], 'compared_quantity': 'Version-specific independent verdicts, correction scope and demo readiness; source numerical claims remain limited to their original referents', 'refutes_us': True}, 'resolution': 'PHENOMENOLOGICAL package counts and runtimes; original scientific levels retained per row', 'time_scale': 'SIMULTANEOUS reader/evidence binding; fabrication-to-measurement remains HANDOVER', 'package': ledger, 'rows': contract['rows'], 'rejections': contract['rejections'], 'frozen_contract': {'path': str(HERE / 'FROZEN_FRONT_X86B.json'), 'sha256': sha(HERE / 'FROZEN_FRONT_X86B.json')}, 'limitations': ['R3 quick profile does not rerun all72 scores or generators; other cache/profile limitations retained', '88 other eligible versions and rejected jakt3 receive only frozen-result hash checks', 'Installed environments and local immutable data required; clean OS untested', 'Whole crown physical function, real patient force and fabricated-vs-predicted calibration unknown', 'Jakt4 exact summary witness FAIL; target coverage missing; no scientific admission'], 'dropout': {'old_registry_not_rerun': {'n': 85, 'total': 97, 'fraction': 85 / 97, 'reason': 'Explicit user scope: only12 front demos'}, 'new_version_not_rerun': {'n': 3, 'total': 3, 'reason': 'Added as reviewed hash-only versions'}, 'rejected_latest_versions': {'n': 1, 'total': 4, 'reason': 'Jakt3 remains REJECT; preserve failures'}, 'execution_failures': ledger['failure_count'], 'hash_failures': ledger['hashes_after']['mismatch_count']}, 'sufficiency': ledger['faults']['sufficiency'] if ledger['faults'] else None}
    write(HERE / 'results.json', result)
    (HERE / 'RESULTS.md').write_text(f"""# Twelve lab operations with version-bound review notifications\n\nThe front of the Sunday package has exactly twelve driving profiles and reports review 26 – 27 : s complete crown and hunting 4 as well as hunting 3 : s continued to reject review 25 version. The external reference of the comparison are the exact independent REVIEW files, not their own physical measurements .\n\n| Administrative measure ( PHENOMENOLOGICAL ) | Actual outcome |\n|---|---|\n| Fresh original profiles | {ledger['pass_count']}/12 PASS; {ledger['failure_count']} error |\n| Total command time / boundary | {time_text(seconds)} /3 600 s |\n| Frozen result , including rejected hunting 3 | {ledger['hashes_after']['pass_count']}/{ledger['hashes_after']['checked']} HASH_PASS |\n| Other valid versions | 88 HASH_ONLY ; no rerun |\n| Physical measurements/Knowledge Status Changes | 0/0 |\n\nR3 ran existing spatial and scorer-controls , exact summary witness and independent tableaudit. All 998 release entries and 29 external dependencies were hash controlled. Dess72 result and three generators were not recalculated. GENCAD V6 and X53 use their packaged short control profiles. The other run their existing packaged profiles; the internal caches documented limitations apply.\n\nTwo state has byteidentical 12 identities/profiles/ frozen expectations, identity error exact 0 ; injected error receipt produces downstream difference 1 . The smallest extension for the couple is a validation piece. Receipt, identity and resulthash controls have run-through error injections. This administrative witness provides no physical conclusion.\n\nComplete crown DIAG / R4 retains 0 / 72 and 0 / 108 full passports, respectively. Jakt4 : s R7 -witness fails on machine identity despite nominal compliance; target_id is null. Jakt3's 1,019891 N is a model scenario with missing mounting facit and demo format. All deflections are preserved. Any parade R4 improvement against R1 – R3 is not established.\n\nAll data is local. The interrupted97-run batch and negative attempts are preserved; no earlier PASS was reused as a fresh rerun. [Executed profiles/times](ALL_DEMOS.md), [raw receipts](raw/x86b/FRONT_REPLAY.json), [frozen selection](FROZEN_FRONT_X86B.json).\n""")
    licenses = '| Local source | License / boundary |\n|---|---|\n| Liu/Hao Demo1 | CC BY 4.0 |\n| Open-Full-Jaw | CC BY-NC-SA 4.0 |\n| Bits2Bites | CC BY - NC - SA ; local version conditions apply |\n| RadRepro | CC BY 4.0 |\n| STS | CC BY 4.0 |\n| ToothFairy2 | CC BY - SA ; local release applies |\n| Mandibeldefekter | CC BY 4.0 |\n| Teeth3DS, Bite2Text, Pulpy3D | UNKNOWN in affected snapshot bindings; check local source ; no new spread state |\n| Publicerade tabellutdrag | Conditions of each article; exact table locators per demo |\n'
    (HERE / 'README_DEMO.md').write_text(_release_expand(f"""# Select and try a lab operation\n\nFrom the same anatomic geometry to CAD , model response and manufacturing/measuring question: the package allows a prosthetic researcher to test twelve reviewed sub-operations with a command. [ FRONT.md ](FRONT.md) shows what each operation can actually determine and the physical measurement that remains.\n\n```bash\ncd @DENTAL_IMPLEMENTATIONS@/X86_FRONT12\n./run_demos.sh\n```\n\n| Outcome | Measured here |\n|---|---|\n| Twelve fresh driving profiles | {ledger['pass_count']}/12 PASS; {ledger['failure_count']} error |\n| Command time with 3 600's boundary | {time_text(seconds)} |\n| Frozen resultshashar | {ledger['hashes_after']['pass_count']}/{ledger['hashes_after']['checked']} correct |\n| Own manufactured specimen against frozen physical prediction | 0 |\n\nPASS applies to the application gate in the specified profile. R3 , GENCAD V6 and X53 run short controls on frozen data. Second versions have been checked without numerical rerun. All profiles and measurement costs are [reported per demo](ALL_DEMOS.md). External reference is the version-bound independent reviews and respective demos source measurement, never a new physical patient measurement.\n\nWhat is not holds : complete crown's form+function/technical connection is continued 0/72 and 0/108 respectively; patient force is UNKNOWN. Jakt3 is rejected. Jakt4 : s exact R7 summary sample fails and target coverage missing. No physical power calibration or manufactured crown is validated in this delivery. Rigorous physical and floating point enclosure are missing where the original model does not deliver it.\n\nLinux, bubblewrap, local datasets and pre-installed Python environments are required; pure OS installation is untested. Execution uses new printable copies, maximum four numeric threads, 60-minute limit and 3 GB own intermediate ceiling including preserved X86 history. No datasets are retrieved. For a single profile, for example, `./run_demos.sh X82` is used; the same twelve identity limit applies.\n\n{licenses}\n![Actual times of the twelve profiles](PACKAGE_AND_LAB_X86B.png)\n"""))
    print('FRONT/ALL_DEMOS/README/RESULTS updated:12 profiles,100 eligible versions,1 rejection')
